# Bypassing Gemini API Rate Limits with Smart Key Rotation in Next.js
## 4. Gemini Call Wrapper (Next.js API Route)
```
// pages/api/gemini-proxy.js
import axios from "axios";
import { selectKey } from "../../lib/rotator";
import { incrementUsage } from "../../lib/rateMonitor";
import { logEvent, alertAdmin } from "../../lib/logger";

const GEMINI_API_BASE = "https://api.gemini.google.com/v1"; // hypothetical
export default async function handler(req, res) {
  const { path, body } = req.body;
  try {
    const { id, apiKey } = await selectKey();
    await incrementUsage(id);
    const resp = await axios.post(
      `${GEMINI_API_BASE}/${path}`,
      body,
      {
        headers: {
          Authorization: `Bearer ${apiKey}`,
        },
      }
    );
    res.status(200).json(resp.data);
  } catch (err) {
    logEvent("ERROR", err.message);
    if (err.response?.status === 429) {
      alertAdmin("Gemini rate limit hit: " + JSON.stringify(err.response.data));
    }
    const status = err.response?.status || 500;
    res.status(status).json({ error: err.message });
  }
}
```

